import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
export interface Job {
  id: string; status: JobStatus; input: string; steps: number; failAttempts: number;
  attempts: number; progress: { completed: number; total: number };
  result: { output: string } | null; error: string | null; createdAt: string; updatedAt: string;
}

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status, available_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id=1), at INTEGER NOT NULL);
  `);
  return db;
}

export function toJob(row: Record<string, unknown>): Job {
  return {
    id: String(row.id), status: row.status as JobStatus, input: String(row.input),
    steps: Number(row.steps), failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.progress_completed), total: Number(row.steps) },
    result: row.result === null ? null : JSON.parse(String(row.result)) as { output: string },
    error: row.error === null ? null : String(row.error),
    createdAt: String(row.created_at), updatedAt: String(row.updated_at),
  };
}

export function getJob(db: DatabaseSync, id: string): Job | null {
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as Record<string, unknown> | undefined;
  return row ? toJob(row) : null;
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, getJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
type FieldError = { field: string; message: string };

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    if (chunks.reduce((n, c) => n + c.length, 0) > 1_000_000) throw new Error('too_large');
  }
  return Buffer.concat(chunks).toString('utf8');
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const heartbeat = db.prepare('SELECT at FROM worker_heartbeat WHERE id = 1').get() as { at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: heartbeat && Date.now() - Number(heartbeat.at) <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
    return send(res, 200, { jobs: rows.map((row) => importJob(row)) });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: FieldError[] = [];
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) {
      return error(res, 400, 'invalid_request', 'Request must use application/json.', [{ field: 'body', message: 'Content-Type must be application/json.' }]);
    }
    let bodyText: string;
    try { bodyText = await readBody(req); } catch {
      return error(res, 400, 'invalid_request', 'Invalid request body.', [{ field: 'body', message: 'Body is too large or unreadable.' }]);
    }
    let value: unknown;
    try { value = JSON.parse(bodyText); } catch {
      return error(res, 400, 'invalid_request', 'Invalid JSON.', [{ field: 'body', message: 'Body must be valid JSON.' }]);
    }
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
      return error(res, 400, 'invalid_request', 'Invalid request body.', [{ field: 'body', message: 'Body must be a JSON object.' }]);
    }
    const obj = value as Record<string, unknown>;
    for (const key of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
    if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({ field: 'input', message: 'Must contain 1 to 1000 characters and not be only whitespace.' });
    const steps = obj.steps === undefined ? 5 : obj.steps;
    const failAttempts = obj.failAttempts === undefined ? 0 : obj.failAttempts;
    if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    const key = req.headers['idempotency-key'];
    if (key !== undefined && (Array.isArray(key) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, digits, underscores, or hyphens.' });
    if (fields.length) return error(res, 400, 'invalid_request', 'Request validation failed.', fields);

    const idemKey = typeof key === 'string' ? key : undefined;
    const payload = JSON.stringify({ input: obj.input, steps, failAttempts });
    if (idemKey !== undefined) {
      const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(idemKey) as { payload: string; job_id: string } | undefined;
      if (existing) {
        if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        const job = getJob(db, existing.job_id);
        if (job) return send(res, 200, job);
      }
    }
    const now = new Date().toISOString(); const id = randomUUID();
    db.exec('BEGIN IMMEDIATE');
    try {
      if (idemKey !== undefined) {
        const raced = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(idemKey) as { payload: string; job_id: string } | undefined;
        if (raced) {
          db.exec('ROLLBACK');
          if (raced.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
          const existingJob = getJob(db, raced.job_id); return existingJob ? send(res, 200, existingJob) : error(res, 500, 'internal_error', 'Stored job is unavailable.');
        }
      }
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0)`).run(id, obj.input as string, steps as number, failAttempts as number, now, now);
      if (idemKey !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(idemKey, payload, id);
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    const job = getJob(db, id);
    return send(res, 201, job);
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const job = getJob(db, id);
    return job ? send(res, 200, job) : error(res, 404, 'not_found', 'Job not found.');
  }
  if (pathname === '/api/jobs') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  return error(res, 404, 'not_found', 'Not found.');
});

// Local converter avoids exposing internal database rows in API payloads.
function importJob(row: Record<string, unknown>) {
  return {
    id: String(row.id), status: row.status, input: row.input, steps: Number(row.steps),
    failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.progress_completed), total: Number(row.steps) },
    result: row.result === null ? null : JSON.parse(String(row.result)),
    error: row.error === null ? null : row.error,
    createdAt: row.created_at, updatedAt: row.updated_at,
  };
}

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown(): void { server.close(() => { db.close(); process.exit(0); }); }
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, toJob } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A worker killed mid-attempt leaves no durable claim. Put it back in the queue and
// let the next process replay that same attempt from its first step.
db.prepare(`UPDATE jobs SET status='queued', attempts=MAX(0, attempts-1), progress_completed=0,
  updated_at=?, available_at=0 WHERE status='running'`).run(new Date().toISOString());

const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(id,at) VALUES(1,?)
  ON CONFLICT(id) DO UPDATE SET at=excluded.at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(() => { try { heartbeat(); } catch { /* shutdown */ } }, 1000);

async function workOne(): Promise<boolean> {
  db.exec('BEGIN IMMEDIATE');
  let row: Record<string, unknown> | undefined;
  try {
    row = db.prepare(`SELECT * FROM jobs WHERE status='queued' AND available_at<=?
      ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as Record<string, unknown> | undefined;
    if (!row) { db.exec('COMMIT'); return false; }
    const now = new Date().toISOString();
    db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0,
      result=NULL, error=NULL, updated_at=? WHERE id=? AND status='queued'`).run(now, String(row.id));
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }
  if (!row) return false;
  const job = toJob(row);
  const started = db.prepare('SELECT attempts FROM jobs WHERE id=?').get(job.id) as { attempts: number };
  const attempt = Number(started.attempts);
  if (attempt <= job.failAttempts) {
    await sleep(100);
    const now = new Date().toISOString();
    if (attempt >= 3) {
      db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result=NULL,
        progress_completed=0, updated_at=? WHERE id=? AND status='running'`).run(now, job.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued', error=NULL, result=NULL, progress_completed=0,
        available_at=?, updated_at=? WHERE id=? AND status='running'`).run(Date.now() + 500, now, job.id);
    }
    return true;
  }
  for (let step = 1; step <= job.steps; step++) {
    if (stopping) return true;
    await sleep(100);
    db.prepare(`UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`)
      .run(step, new Date().toISOString(), job.id);
  }
  db.prepare(`UPDATE jobs SET status='completed', result=?, error=NULL, progress_completed=steps,
    updated_at=? WHERE id=? AND status='running'`).run(JSON.stringify({ output: job.input.toUpperCase() }), new Date().toISOString(), job.id);
  return true;
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const worked = await workOne();
    if (!worked) await sleep(100);
  }
} finally {
  clearInterval(heartbeatTimer);
  // If shutdown interrupted a job, make it available to the next worker immediately.
  db.prepare(`UPDATE jobs SET status='queued', attempts=MAX(0, attempts-1), progress_completed=0,
    updated_at=?, available_at=0 WHERE status='running'`).run(new Date().toISOString());
  db.close();
}
