    const list = document.querySelector('[data-testid="job-list"]');
    const alertRegion = document.querySelector('[data-testid="form-error"]');
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li'); item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
        const title = document.createElement('strong'); title.textContent = job.input;
        const status = document.createElement('div'); status.dataset.testid = 'job-status'; status.textContent = job.status;
        const progress = document.createElement('div'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
        const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result ? job.result.output : (job.error || '');
        const meta = document.createElement('div'); meta.className = 'meta'; meta.textContent = `Attempts: ${job.attempts} · Created: ${new Date(job.createdAt).toLocaleString()}`;
        item.append(title, status, progress, result, meta); return item;
      }));
    }
    async function refresh() {
      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); }
      catch (_) { /* a later poll will refresh */ }
    }
    document.querySelector('[data-testid="job-form"]').addEventListener('submit', async event => {
      event.preventDefault(); alertRegion.textContent = '';
      const form = new FormData(event.currentTarget);
      const payload = { input: form.get('input'), steps: Number(form.get('steps')), failAttempts: Number(form.get('failAttempts')) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
        const body = await response.json();
        if (!response.ok) {
          const fields = body.error?.fields || [];
          alertRegion.textContent = fields.length ? fields.map(f => `${f.field}: ${f.message}`).join(' ') : body.error?.message || 'Request failed.';
        } else { event.currentTarget.reset(); document.querySelector('[data-testid="job-steps"]').value = '5'; document.querySelector('[data-testid="job-fail-attempts"]').value = '0'; }
        await refresh();
      } catch (_) { alertRegion.textContent = 'Unable to submit job.'; }
    });
    refresh(); setInterval(refresh, 500);
  </script>
